* { box-sizing: border-box; }

:root {
  font-family: system-ui, -apple-system, Segoe UI, sans-serif;
  color: #182233;
  background: #f4f7f9;
}

body {
  margin: 0;
  background:
    radial-gradient(circle at 90% 0%, #d8edf6, transparent 26rem),
    #f4f7f9;
}

main {
  width: min(1040px, calc(100% - 36px));
  margin: 0 auto;
}

.hero {
  padding: 62px 0 46px;
  border-bottom: 1px solid #d5dfe7;
}

.brand-row {
  display: flex;
  gap: 12px;
  align-items: center;
  color: #59697b;
  font-size: .9rem;
}

.mark, .eyebrow {
  color: #086ea1;
  font-size: .76rem;
  font-weight: 800;
  letter-spacing: .15em;
}

.forge-motto {
  padding-left: 12px;
  border-left: 1px solid #b9c7d2;
}

h1 {
  max-width: 820px;
  margin: 12px 0 16px;
  font-size: clamp(3rem, 9vw, 6rem);
  line-height: .95;
  letter-spacing: -.055em;
}

h2 { margin: 7px 0 12px; }
h3 { margin: 8px 0 6px; }

.lede,
p {
  color: #59697b;
  line-height: 1.6;
}

.lede {
  max-width: 720px;
  margin-bottom: 0;
  font-size: 1.15rem;
}

.builder {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 34px;
  padding: 44px 0;
  border-bottom: 1px solid #d5dfe7;
}

.controls,
.project-card {
  padding: 26px;
  border: 1px solid #d1dce5;
  border-radius: 12px;
  background: rgba(255,255,255,.86);
}

label {
  display: block;
  margin: 18px 0 6px;
  color: #34475a;
  font-weight: 700;
}

input,
select {
  width: 100%;
  padding: 11px 12px;
  border: 1px solid #b8c7d3;
  border-radius: 6px;
  background: white;
  color: #182233;
  font: inherit;
}

input:focus-visible,
select:focus-visible,
button:focus-visible {
  outline: 3px solid #52bde8;
  outline-offset: 2px;
}

.button-row {
  display: flex;
  gap: 9px;
  margin-top: 16px;
}

button {
  padding: 10px 15px;
  border: 1px solid #086ea1;
  border-radius: 6px;
  background: #086ea1;
  color: white;
  font: inherit;
  font-weight: 750;
  cursor: pointer;
}

button.secondary {
  background: white;
  color: #086ea1;
}

button.small {
  padding: 5px 8px;
  font-size: .78rem;
}

button.remove {
  border-color: #b7c3cd;
  color: #526474;
}

.project-card {
  background: #172331;
  color: white;
}

.project-card h2 { color: white; }

.project-card-top,
.progress-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
}

.project-card-top {
  color: #b6c7d5;
  font-size: .8rem;
}

.file-mark {
  padding: 4px 8px;
  border: 1px solid #405569;
  border-radius: 999px;
}

.idea-preview {
  min-height: 52px;
  color: #dce8f0;
  font-size: 1.08rem;
}

.progress-row {
  margin-top: 20px;
  color: #c0cfda;
  font-size: .86rem;
}

.progress-track {
  height: 8px;
  margin: 8px 0 18px;
  overflow: hidden;
  border-radius: 999px;
  background: #304252;
}

.progress-bar {
  width: 0;
  height: 100%;
  background: #52bde8;
  transition: width .2s ease;
}

.plan-list {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.plan-item {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 9px;
  align-items: center;
  padding: 9px;
  border: 1px solid #405569;
  border-radius: 7px;
}

.plan-item.done .plan-text {
  color: #91a8b9;
  text-decoration: line-through;
}

.plan-item button {
  margin: 0;
}

.plan-item .check {
  min-width: 34px;
}

.plan-item .remove {
  background: transparent;
}

.principles {
  padding: 48px 0 24px;
}

.grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  margin-top: 22px;
  border-top: 1px solid #d5dfe7;
}

article {
  padding: 24px 22px 26px 0;
  border-bottom: 1px solid #d5dfe7;
}

article + article {
  padding-left: 22px;
  border-left: 1px solid #d5dfe7;
}

article b {
  color: #718397;
  font: .75rem monospace;
}

code {
  padding: 2px 5px;
  border-radius: 4px;
  background: #e1e8ee;
}

.inspect {
  display: grid;
  grid-template-columns: 1.15fr .85fr;
  gap: 44px;
  align-items: center;
  padding: 50px 0;
}

.files {
  display: grid;
  gap: 9px;
}

.files div {
  padding: 13px 15px;
  border: 1px solid #d1dce5;
  border-radius: 7px;
  background: white;
  font-family: monospace;
}

.files span {
  display: inline-block;
  width: 48px;
  color: #086ea1;
  font-weight: bold;
}

footer {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding: 22px 0 36px;
  border-top: 1px solid #d5dfe7;
  color: #667789;
  font-size: .85rem;
}

@media (prefers-reduced-motion: reduce) {
  .progress-bar { transition: none; }
}

@media (max-width: 760px) {
  .builder,
  .grid,
  .inspect {
    grid-template-columns: 1fr;
  }

  article,
  article + article {
    padding: 22px 0;
    border-left: 0;
  }

  footer {
    flex-direction: column;
  }
}

const starterIdea = 'Make review feedback easier to act on.';
const starterSteps = [
  'Describe the smallest useful outcome',
  'Try it with one person'
];

const ideaInput = document.getElementById('ideaInput');
const ideaPreview = document.getElementById('ideaPreview');
const capabilitySelect = document.getElementById('capabilitySelect');
const planList = document.getElementById('planList');
const progressText = document.getElementById('progressText');
const progressBar = document.getElementById('progressBar');
const statusText = document.getElementById('statusText');

let steps = starterSteps.map(text => ({ text, done: false }));

function render() {
  ideaPreview.textContent = ideaInput.value.trim() || 'Untitled idea';
  planList.textContent = '';

  steps.forEach((step, index) => {
    const item = document.createElement('li');
    item.className = `plan-item${step.done ? ' done' : ''}`;

    const check = document.createElement('button');
    check.type = 'button';
    check.className = 'small check';
    check.textContent = step.done ? 'Done' : 'Do';
    check.setAttribute(
      'aria-label',
      `${step.done ? 'Mark incomplete' : 'Mark complete'}: ${step.text}`
    );
    check.addEventListener('click', () => {
      steps[index].done = !steps[index].done;
      statusText.textContent = steps[index].done
        ? 'Step completed'
        : 'Step reopened';
      render();
    });

    const text = document.createElement('span');
    text.className = 'plan-text';
    text.textContent = step.text;

    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'small secondary remove';
    remove.textContent = 'Remove';
    remove.setAttribute('aria-label', `Remove: ${step.text}`);
    remove.addEventListener('click', () => {
      steps.splice(index, 1);
      statusText.textContent = 'Step removed';
      render();
    });

    item.append(check, text, remove);
    planList.appendChild(item);
  });

  const done = steps.filter(step => step.done).length;
  const percent = steps.length ? Math.round((done / steps.length) * 100) : 0;

  progressText.textContent = `${done} / ${steps.length}`;
  progressBar.style.width = `${percent}%`;
}

ideaInput.addEventListener('input', render);

document.getElementById('addBtn').addEventListener('click', () => {
  const text = capabilitySelect.value;

  if (!steps.some(step => step.text === text)) {
    steps.push({ text, done: false });
    statusText.textContent = 'Step added';
  } else {
    statusText.textContent = 'That step is already in the plan';
  }

  render();
});

document.getElementById('resetBtn').addEventListener('click', () => {
  ideaInput.value = starterIdea;
  steps = starterSteps.map(text => ({ text, done: false }));
  statusText.textContent = 'Plan reset';
  render();
});

render();
